const MOD = 1000000007;

// Read input
const readline = require('readline').createInterface({
  input: process.stdin,
  output: process.stdout
});

readline.on('line', (line) => {
  const [xStr, nStr] = line.trim().split(' ');
  const x = parseInt(xStr);
  const n = BigInt(nStr);

  // Get prime factors of x
  const primes = getPrimeFactors(x);

  let result = 1n;

  for (const p of primes) {
    const pBig = BigInt(p);
    let exponent = 0n;
    let current = pBig;
    while (current <= n) {
      exponent += n / current;
      current *= pBig;
    }
    // Multiply result by p^exponent mod MOD
    result = modPow(pBig, exponent, BigInt(MOD)) * result % BigInt(MOD);
  }

  console.log(result.toString());
  readline.close();
});

// Function to get prime factors of x
function getPrimeFactors(x) {
  const factors = new Set();
  let num = x;
  for (let i = 2; i * i <= num; i++) {
    while (num % i === 0) {
      factors.add(i);
      num /= i;
    }
  }
  if (num > 1) {
    factors.add(num);
  }
  return Array.from(factors);
}

// Modular exponentiation for BigInt
function modPow(base, exponent, mod) {
  let result = 1n;
  base = base % mod;
  while (exponent > 0n) {
    if (exponent % 2n === 1n) {
      result = (result * base) % mod;
    }
    exponent = exponent >> 1n;
    base = (base * base) % mod;
  }
  return result;
}
